using NUnit.Framework;
using Shazdeh.Core.Text;

namespace Shazdeh.Core.Tests
{
    /// <summary>
    /// The fa-IR requirement, tested. Every expected string comes from
    /// client/Assets/Core.Tests/Generated/PersianGoldenVectors.gen.cs, which is generated by
    /// tools/text/persian_ref.py — and that script cross-checks its own shaping against
    /// `arabic-reshaper` on the same 33 strings. So these tests compare our C# against a second
    /// implementation, not against the same code written twice by one author.
    /// </summary>
    public sealed class PersianTextTests
    {
        const char Zwnj = '\u200C';

        [Test]
        public void ShapingMatchesTheGeneratedVectors()
        {
            var failures = new System.Text.StringBuilder();

            for (int i = 0; i < PersianGoldenVectors.Strings.Length; i++)
            {
                var vector = PersianGoldenVectors.Strings[i];
                string shaped = PersianText.Shape(vector.Logical);
                if (shaped != vector.Shaped)
                    failures.AppendLine("Shape(" + vector.Logical + ") = " + shaped + ", expected " + vector.Shaped);
            }

            Assert.AreEqual(0, failures.Length, failures.ToString());
        }

        [Test]
        public void VisualOrderMatchesTheGeneratedVectors()
        {
            var failures = new System.Text.StringBuilder();

            for (int i = 0; i < PersianGoldenVectors.Strings.Length; i++)
            {
                var vector = PersianGoldenVectors.Strings[i];
                string visual = PersianText.ToVisualOrder(vector.Shaped);
                if (visual != vector.Visual)
                    failures.AppendLine("ToVisualOrder(" + vector.Shaped + ") = " + visual + ", expected " + vector.Visual);

                string display = PersianText.ForDisplay(vector.Logical);
                if (display != vector.Visual)
                    failures.AppendLine("ForDisplay(" + vector.Logical + ") = " + display + ", expected " + vector.Visual);
            }

            Assert.AreEqual(0, failures.Length, failures.ToString());
        }

        [Test]
        public void ShapingIsIdempotent()
        {
            // Presentation forms are not letters, so a second pass must change nothing. This matters
            // because a screen may set the same label twice.
            for (int i = 0; i < PersianGoldenVectors.Strings.Length; i++)
            {
                string once = PersianText.Shape(PersianGoldenVectors.Strings[i].Logical);
                Assert.AreEqual(once, PersianText.Shape(once), PersianGoldenVectors.Strings[i].Logical);
            }
        }

        [Test]
        public void EveryLetterOfASimpleWordTakesAContextualForm()
        {
            // "کاخ" — kaf initial, alef final, kheh final: three letters, and none of them may still
            // be sitting in the base Arabic block once shaping is done.
            string shaped = PersianText.Shape("کاخ");

            Assert.AreEqual(3, shaped.Length);
            foreach (char c in shaped)
                Assert.IsTrue(c >= '\uFB50', "every letter should have become a presentation form: " + shaped);
        }

        [Test]
        public void LamAlefBecomesOneGlyph()
        {
            string shaped = PersianText.Shape("سلام");

            Assert.IsFalse(shaped.Contains("\u0644"), "lam should be part of the ligature");
            Assert.IsFalse(shaped.Contains("\u0627"), "alef should be consumed by the ligature");
            Assert.IsTrue(shaped.Contains("\uFEFC") || shaped.Contains("\uFEFB"),
                "lam-alef ligature expected, got " + shaped);
        }

        [Test]
        public void AZwnjStopsTheJoin()
        {
            string withBreak = PersianText.Shape("می" + Zwnj + "روم");
            string withoutBreak = PersianText.Shape("میروم");

            Assert.AreNotEqual(withBreak, withoutBreak, "a zero-width non-joiner must change the forms");
            Assert.IsFalse(withBreak.Contains(Zwnj), "the joiner itself is not a glyph and is dropped");
            Assert.IsFalse(PersianText.ForDisplay("می" + Zwnj + "روم").Contains(Zwnj));
        }

        [Test]
        public void ALatinWordInsideAPersianSentenceKeepsItsLetters()
        {
            string display = PersianText.ForDisplay("متن Royal Match در جمله");

            Assert.IsTrue(display.Contains("Royal Match"), "Latin runs are never reversed: " + display);
            Assert.Greater(display.IndexOf("Royal", System.StringComparison.Ordinal), 0,
                "in an RTL line the Latin run is not the first thing drawn: " + display);

            // Nothing outside the Latin run may contain Latin letters.
            string stripped = display.Replace("Royal Match", "");
            foreach (char c in stripped)
                Assert.IsFalse((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'), "stray Latin letter in " + display);
        }

        [Test]
        public void PlainLatinIsUntouched()
        {
            Assert.AreEqual("Royal Match", PersianText.ForDisplay("Royal Match"));
            Assert.AreEqual("Level 5", PersianText.ForDisplay("Level 5"));
            Assert.AreEqual("", PersianText.ForDisplay(""));
            Assert.AreEqual("", PersianText.ForDisplay(null));
            Assert.AreEqual("", PersianText.Shape(null));
        }

        [Test]
        public void BracketsAreMirroredInPersianText()
        {
            string display = PersianText.ForDisplay("شازده (کاخ)");

            // A mirrored pair still encloses its word when read left to right: the glyph that opened
            // logically becomes the one drawn on the right, and the pair keeps the word between them.
            Assert.IsTrue(display.Contains("("), display);
            Assert.IsTrue(display.Contains(")"), display);
            Assert.Less(display.IndexOf('('), display.IndexOf(')'),
                "after mirroring the pair still encloses the word: " + display);
        }

        [Test]
        public void NumbersKeepTheirOrderInsideAPersianSentence()
        {
            string display = PersianText.ForDisplay("۲۵ معجون");

            // A number is an LTR run: ۲۵ must stay "۲۵" (two then five), not "۵۲".
            int two = display.IndexOf('\u06F2');
            int five = display.IndexOf('\u06F5');
            Assert.GreaterOrEqual(two, 0);
            Assert.GreaterOrEqual(five, 0);
            Assert.Less(two, five, "digits must keep their own order: " + display);
        }

        [Test]
        public void NumberFormattingUsesPersianDigitsAndSeparators()
        {
            for (int i = 0; i < PersianGoldenVectors.NumberValues.Length; i++)
            {
                long value = PersianGoldenVectors.NumberValues[i];
                Assert.AreEqual(PersianGoldenVectors.NumberText[i], PersianText.Number(value), "Number(" + value + ")");
            }
        }

        [Test]
        public void NumberGroupingIsThreeDigits()
        {
            Assert.AreEqual("۱٬۲۳۴", PersianText.Number(1234));
            Assert.AreEqual("۱۲٬۳۴۵٬۶۷۸", PersianText.Number(12345678));
            Assert.AreEqual("۱۰۰", PersianText.Number(100));

            foreach (char c in PersianText.Number(123456789))
                Assert.IsTrue(c == '\u066C' || PersianText.IsPersianDigit(c), "no ASCII digits may leak into the UI");
        }

        [Test]
        public void CountdownsReadLikeAClock()
        {
            for (int i = 0; i < PersianGoldenVectors.TimeValues.Length; i++)
            {
                int seconds = PersianGoldenVectors.TimeValues[i];
                Assert.AreEqual(PersianGoldenVectors.TimeText[i], PersianText.Time(seconds), "Time(" + seconds + ")");
            }

            Assert.AreEqual("۲۹:۵۹", PersianText.Time(1799));
            Assert.AreEqual("۰۰:۰۰", PersianText.Time(-10));
        }

        [Test]
        public void DigitsConvertBothWays()
        {
            Assert.AreEqual("۰۱۲۳۴۵۶۷۸۹", PersianText.ToPersianDigits("0123456789"));
            Assert.AreEqual("0123456789", PersianText.ToLatinDigits("۰۱۲۳۴۵۶۷۸۹"));
            Assert.AreEqual("مرحله ۷", PersianText.ToPersianDigits("مرحله 7"));
            Assert.AreEqual("مرحله 7", PersianText.ToLatinDigits("مرحله ۷"));

            string mixed = "سطح ۱۲ از ۲۰ — ۱٬۲۳۴";
            Assert.AreEqual(mixed, PersianText.ToPersianDigits(PersianText.ToLatinDigits(mixed)));
        }

        [Test]
        public void TheOutputIsNeverTheInputUntouched()
        {
            // Guard against a future "optimisation" that returns the input untouched.
            Assert.AreNotEqual("کاخ شازده", PersianText.ForDisplay("کاخ شازده"));
            Assert.AreNotEqual("کاخ شازده", PersianText.Shape("کاخ شازده"));
        }
    }
}
